class Inventory(HTMLParser):
    def __init__(self, name):
        super().__init__(); self.name=name; self.items=[]; self.line=0
    def handle_starttag(self,tag,attrs):
        a=dict(attrs)
        if tag in ('input','select','textarea','button'):
            self.items.append(dict(file=self.name,line=self.getpos()[0],tag=tag,**a))

