def btn(s,primary=False,disabled=False):return f'<button type="button" class="{"primary" if primary else ""}" {"disabled" if disabled else ""}>{s}</button>'
def small(s):return f'<button type="button" class="small link">{s}</button>'
def badge(s,kind=''):return f'<span class="badge {kind}">{s}</span>'
def field(label,value='未選択',kind='select',req=False,full=False,source='',help=''):
    reqs='<span class="req">必須</span>' if req else '<span class="optional">任意</span>'
    if kind=='textarea':control=f'<textarea>{escape(value)}</textarea>'
    elif kind=='multi':control='<select multiple size="4">'+''.join(f'<option>{escape(v)}</option>' for v in value.split('|'))+'</select>'
    elif kind=='select':control=f'<select><option>{escape(value)}</option></select>'
    else:control=f'<input type="{kind}" value="{escape(value)}">'
    return f'<div class="field {"full" if full else ""}" data-source-control="{source}"><label>{label}{reqs}</label>{control}'+(f'<div class="hint">{help}</div>' if help else '')+'</div>'
def neutral(label,value,kind='select',source=''):return field(label,value,kind,source=source).replace('<span class="optional">任意</span>','')
def choose(label,options,source='',req=False,full=False):
    normalized=[item if isinstance(item,tuple) else (item,item) for item in options]
    reqs='<span class="req">必須</span>' if req else ''
    return f'<div class="field {"full" if full else ""}" data-source-control="{source}"><label>{label}{reqs}</label><select>'+''.join(f'<option value="{escape(str(value))}">{escape(str(text))}</option>' for value,text in normalized)+'</select></div>'
def grid(items,cols=''):return f'<div class="grid {cols}">'+''.join(items)+'</div>'
def card(title,body):return f'<section class="card"><h2>{title}</h2>{body}</section>'
def actions(*items):return '<div class="actions">'+''.join(items)+'</div>'
def note(s,kind=''):return f'<div class="notice {kind}">{s}</div>'
def detail(title,body,opened=False):return f'<details {"open" if opened else ""}><summary>{title}</summary>{body}</details>'
def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def checks(items):return '<div class="checks">'+''.join(f'<label><input type="checkbox"> {i}</label>' for i in items)+'</div>'
def stats(items):return '<div class="statrow">'+''.join(f'<div class="stat"><span>{a}</span><strong>{b}</strong></div>' for a,b in items)+'</div>'
def page(key,title,subtitle,body,active=None,annotation=''):
    # One bounded source/geometry correction round, recorded in visual-errata.md.
    if key=='05-pitchbook-form':
        body=body.replace('<th>操作</th>','<th>状態</th>').replace(small('除外'),badge('選択済み','off'))
        pitch_actions=actions(btn('登録',True),btn('ファイル下書きをクリア'),btn('失敗分を再試行',disabled=True))
        pitch_footer='<div class="editor-footer">'+pitch_actions+'</div>'
        body=body.replace(pitch_actions,pitch_footer)
        pitch_table=table(['選択ファイル','サイズ','状態'],[['サンプル資料.pdf','2.4 MB',badge('選択済み','off')]])
        body=body.replace(pitch_table+pitch_footer,pitch_footer+pitch_table)
    if key=='03-pitchbooks':
        body=body.replace(small('原資料 ↗')+' '+small('復元'),small('原資料 ↗')+' '+small('編集')+' '+small('復元'))
    if key=='02-meetings':
        body=body.replace('MTG-000101</span>','MTG-000101 / 更新版 1</span>').replace('MTG-000102</span>','MTG-000102 / 更新版 1</span>')
    if key=='07-entity':
        body=body.replace('<td>'+fund+'</td>', '<td>'+small(fund)+'</td>')
        body+=card('活動の内訳',table(['Team','Asset Class','Meeting Type'],[['サンプルチーム：1','Infrastructure：1','未設定：1']]))+card('Activity timeline',table(['日付','種類 / ID','状態'],[['2026-09-02','Meeting / MTG-000102',badge('削除済み','off')],['2026-09-02','Pitchbook / DOC-000201',badge('有効')]]))
    if key=='08-analytics':
        body=body.replace(table(['面談先区分','件数','操作'],[['GP / 運用会社','1',small('詳細')],['LP / Asset Owner','1',small('詳細')]]),table(['面談先区分','面談','有効','面談先数','要フォロー'],[['GP / 運用会社','1','1','1','1'],['LP / Asset Owner','1','0','1','0']]))
        body=body.replace(chart,stats([('面談','2'),('有効','1'),('面談先数','2'),('要フォロー','1')])+chart+table(['期間','面談','有効','面談先数','要フォロー'],[['2026-09','2','1','2','1']]))
        body=body.replace(recent_m,table(['日付','Meeting ID','面談先キー','関連GP ID','Team / Type','状態','原資料'],[['2026-09-03','MTG-000101','GP:GP-SAMPLE-A','GP-SAMPLE-A','TEAM-SAMPLE / ANNUAL_REVIEW',badge('有効'),small('Doc ↗')],['2026-09-02','MTG-000102','LP:OPT-SAMPLE-LP','GP-SAMPLE-A','TEAM-SAMPLE / —',badge('削除済み','off'),small('Doc ↗')]]))
        body+=card('月次管理操作の条件付き状態例',table(['Meeting','日付','面談先キー','状態','操作'],[['MTG-000101','2026-09-03','GP:GP-SAMPLE-A','未反映',small('反映済みにする')],['MTG-000102','2026-09-02','LP:OPT-SAMPLE-LP','反映済み',small('未反映に戻す')]]))
    if key=='09-relationships':
        body=body.replace('<section class="card"><h2>面談 → 資料',stats([('明示的な関係','3'),('面談','1'),('解決済み資料','2'),('未解決','1')])+'<p class="hint">削除済み面談：0 / 削除済み資料：1 · 表示省略：0</p><section class="card"><h2>面談 → 資料')
    if key.startswith('11'):
        body=body.replace('<div class="field " data-source-control=""><label>Thinking profiles','<div class="field full" data-source-control=""><label>Thinking profiles')
    active=active or key; nav=''.join(f'<h3>{g}</h3>'+''.join(f'<a href="{k}.html" class="{"active" if k==active else ""}">{v}</a>' for k,v in items) for g,items in NAV)
    html=f'<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} — Light design reference</title><link rel="stylesheet" href="family.css"><body><aside><div class="brand">Knowledge Share<small>PRIVATE ASSETS KNOWLEDGE</small></div><nav>{nav}</nav><img class="motif" src="sayagata.svg" alt=""></aside><main><header class="heading"><div><div class="eyebrow">KNOWLEDGE SHARE / LIGHT FAMILY</div><h1>{title}</h1><p class="subtitle">{subtitle}</p></div><span class="hint">設計参照 · 架空データ</span></header>{body}<footer class="annotation">DESIGN ONLY · 0028-CODEX-04 · 操作・保存・通信処理なし。{annotation}</footer></main></body></html>'
    html=html.replace('<img class="motif" src="sayagata.svg" alt="">','<div class="motif" aria-hidden="true"></div>')
    (OUT/(key+'.html')).write_text(html,encoding='utf-8'); pages.append({'file':key+'.html','title':title,'active':active})

