    controls+=actions(*[btn(s) for s in (['APIキーを保存してStore確認','資格済みGeminiを有効化','Geminiを無効化','選択資料を個別同期'] if gemini else ['APIキーを保存して接続確認','OpenAIを無効化','資料を同期して利用開始'])])
